'use strict';
/* 픽스처 — «존재형» 축(F602 · 2026-08-18)의 탐지력을 값으로 못박는 재료다.
 * 돌아가지 않는다(파일명에 `.test.js` 를 안 붙인 것도 그래서다 — 붙이면 러너가 실행하려 든다).
 *
 * 왜 뿌리가 «또» 따로인가: ②(㉡ census)·②-b(불투명 import)·②-c(세 경계)와 같은 이유다 —
 *   한 뿌리에 축을 섞으면 어느 축이 깨졌는지 안 보인다. 특히 여기는 **부정 축의 숫자를
 *   건드리지 않는 것**이 중요하다: 이 픽스처가 재는 것은 「부정과 존재가 안 섞이는가」다.
 *
 * 재는 것 넷:
 *   ① 존재형 네 모양을 다 잡나 — `match` · `ok(…includes)` · `equal(…, true)` · `notEqual(…, -1)`
 *   ② 정제 경유는 «안전»으로 서나 (옳게 감쌌는데 숫자가 안 움직이면 아무도 안 감싼다 · F103)
 *   ③ 방향이 안 섞이나 — 부정형은 존재 통에 **안 든다**(반대도 마찬가지)
 *   ④ 언어를 가르나 — `.sql` 을 읽는 자리는 `코드만`(JS 렉서) 처방이 안 서므로 «아님»으로 선다
 */

const fs = require('fs');
const assert = require('assert');
const { 코드만 } = require('../../../lib/소스검사.js');

const 소스 = fs.readFileSync('화면.js', 'utf8');        // 원문 · 언어 js
const 스키마 = fs.readFileSync('스키마.sql', 'utf8');   // 원문 · 언어 아님(SQL 주석은 `--` 다)
const 깨끗 = 코드만(fs.readFileSync('도구.js', 'utf8')); // 정제 경유

/* ── ① 존재위험(js) 네 모양 — 넷 다 「이 낱말이 **있어야** 한다」다 ────────────────
 * 하나라도 놓치면 그 모양의 검사가 «영원히 초록»인 채 산다: 코드에서 낱말이 사라져도
 * 바로 위 주석이 그것을 설명하고 있으면 통과한다(F401 첫 사례 = `for update`). */
assert.match(소스, /낱말가/);                    // ①-a 첫 인자가 곧 수신자(글에 `.match(` 가 없다)
assert.ok(소스.includes('낱말나'));              // ①-b
assert.equal(소스.includes('낱말다'), true);     // ①-c
assert.notEqual(소스.indexOf('낱말라'), -1);     // ①-d `!== -1` 관용구

/* ⑤ 이중 부정은 «존재»다 — `!` 를 먼저 보고 「부정」으로 접으면 여기가 부정 통에 잘못 든다. */
assert.equal(!소스.includes('낱말사'), false);

/* ── ③ 언어 — SQL 을 읽는 자리는 «아님». 여기에 「`코드만` 으로 감싸라」고 말하면
 *   따를 수 없는 처방이 되고, 따를 수 없는 처방은 우회를 정상 통로로 만든다(F103). */
assert.match(스키마, /create table/);

/* ── ② 정제 경유 — «안전»으로 서야 한다 ─────────────────────────────────────── */
assert.match(깨끗, /낱말마/);
assert.ok(깨끗.includes('낱말바'));

/* ── ④ 방향이 안 섞인다 — 아래 셋은 부정 통(위험)에만 들어야 한다 ────────────────
 * `doesNotMatch` 는 존재 축을 열면서 **처음** 보이게 된 모양이다: 글에 술어가 없어
 * 옛 판의 술어 관문에서 통째로 떨어졌다(부정 축의 사각이었다). */
assert.ok(!소스.includes('금지가'));
assert.doesNotMatch(소스, /금지나/);
assert.equal(소스.includes('금지다'), false);

/* ── ⑥ 세면 «안 된다» — 수신자가 문자열 상수다(재는 대상이 소스가 아니다) ────────── */
assert.match('상수 글 — 파일이 아니다', /낱말/);
assert.ok('상수 글 — 파일이 아니다'.includes('낱말'));

/* ── ⑦ ❔모름 — 수신자가 런타임 값이라 못 가른다. 위험으로 세면 처방이 「런타임 객체를
 *   감싸라」가 된다(F103). 모름은 미탐이 아니라 «분모에 남는» 상태다. */
assert.match(결과.본문, /낱말아/);   // eslint-disable-line no-undef
